 59	export const VoiceMessage: FC<Props> = ({
 60	  event,
 61	  isPreviousSameSender,
 62	  onMemberPress,
 63	}) => {
 64	  const content = getAudioContent(event);
 65	  const eventId = getEventId(event);
 66	  const playbackId =
 67	    "inner" in event.eventOrTransactionId
 68	      ? "eventId" in event.eventOrTransactionId.inner
 69	        ? event.eventOrTransactionId.inner.eventId
 70	        : event.eventOrTransactionId.inner.transactionId
 71	      : String(event.timestamp);
 72	  const [messageWidth, setMessageWidth] = useState(40);
 73	  const [isLoading, setIsLoading] = useState(false);
 74	  const isUser = event.isOwn;
 75	  const sender = event.senderProfile;
 76	  const senderId = event.sender;
 77	  const duration = content?.info?.duration ?? 0;
 78	  const maxWidth = width - 60; // Minus horizontal paddings and 20 extra to prevent to be too wide
 79	  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
 80	  const { isPlaying, currentMs, play, pause, resume } =
 81	    useAudioPlayback(playbackId);
 82	
 83	  useEffect(() => {
 84	    TimelineService.getReadReceipts(event)
 85	      .then((users) => {
 86	        setSeenBy(users);
 87	      })
 88	      .catch((error) => {
 89	        console.error("Failed to get read receipt users:", error);
 90	        setSeenBy([]);
 91	      });
 92	  }, [event]);
 93	
 94	  const onTogglePlay = async () => {
 95	    //For these types of voice messages, we need to convert them to m4a with ffmpeg
 96	    if (["audio/ogg", "audio/opus"].includes(content?.info?.mimetype ?? "")) {
 97	      Toast.show({
 98	        type: "error",
 99	        text1: "This voice message is not supported on this device.",
100	      });
101	      return;
102	    }
103	
104	    try {
105	      setIsLoading(true);
106	
107	      if (isPlaying) {
108	        await pause();
109	        return;
110	      }
111	
112	      // If paused mid-track and not at the end, resume instead of restarting
113	      if (currentMs > 0 && currentMs < duration) {
114	        await resume();
115	        return;
116	      }
117	
118	      // Re-fetch the playback URL to ensure it's valid (temp files may be cleaned up)
119	      if (!content?.source || !MatrixCore.instance) {
120	        Toast.show({
121	          type: "error",
122	          text1: "Failed to fetch voice message.",
123	        });
124	        return;
